import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import './Login.css';

const Login = () => {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    correo: '',
    contraseña: ''
  });
  const [msg, setMsg] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm(prev => ({
      ...prev,
      [name]: value
    }));
    setMsg(''); // Limpiar mensajes de error al cambiar
  };

  const togglePassword = () => {
    setShowPassword(!showPassword);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!form.correo || !form.contraseña) {
      setMsg('Por favor completa todos los campos.');
      return;
    }

    setLoading(true);
    setMsg('');

    try {
      const response = await axios.post('http://localhost:3000/api/auth/login', {
        correo: form.correo,
        contraseña: form.contraseña
      });

      if (response.data.success) {
        localStorage.setItem('token', response.data.token);
        localStorage.setItem('usuario', JSON.stringify(response.data.usuario));
        
        // Redirigir según el rol
        if (response.data.usuario.rol === 'administrador') {
          console.log('Redirigiendo a dashboard-admin');
          navigate('/dashboard-admin');
        } else if (response.data.usuario.rol === 'artesano') {
          console.log('Redirigiendo a dashboard-artesano');
          navigate('/dashboard-artesano');
        } else {
          console.log('Redirigiendo a home');
          navigate('/');
        }
      }
    } catch (error) {
      console.error('Error en login:', error);
      if (error.response && error.response.data && error.response.data.message) {
        setMsg(error.response.data.message);
      } else {
        setMsg('Error al iniciar sesión. Por favor verifica tus credenciales.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-page">
      <div className="main-container">
        <div className="login-container">
          {/* Left Column - Welcome Card */}
          <div className="left-column">
            {/* Decorative Patterns */}
            <div className="decorative-patterns">
              <div className="pattern-circle-1"></div>
              <div className="pattern-circle-2"></div>
              <div className="pattern-circle-3"></div>
              <div className="pattern-square"></div>
            </div>

            {/* Content */}
            <div className="content">
              <div className="welcome-header">
                <div className="welcome-icon">🎭</div>
                <h2 className="welcome-title">¡Hola,<br/>Bienvenido!</h2>
              </div>

              <p className="welcome-description">
                Nos emociona verte de nuevo en Artisa. Donde cada obra de arte tiene su propia historia.
              </p>

              <div className="contact-info">
                <div className="contact-item">
                  <div className="contact-icon">📞</div>
                  <div>
                    <div className="contact-label">Teléfono</div>
                    <div className="contact-value">+1 (555) 123-4567</div>
                  </div>
                </div>

                <div className="contact-item">
                  <div className="contact-icon">✉️</div>
                  <div>
                    <div className="contact-label">Email</div>
                    <div className="contact-value">soporte@artisa.com</div>
                  </div>
                </div>

                <div className="contact-item">
                  <div className="contact-icon">📍</div>
                  <div>
                    <div className="contact-label">Ubicación</div>
                    <div className="contact-value">Ciudad de México</div>
                  </div>
                </div>
              </div>

              {/* Social Media */}
              <div className="social-section">
                <h3 className="social-title">Síguenos</h3>
                <div className="social-links">
                  <a href="#" className="social-link" aria-label="Facebook">📘</a>
                  <a href="#" className="social-link" aria-label="Instagram">📷</a>
                  <a href="#" className="social-link" aria-label="Twitter">🐦</a>
                </div>
              </div>

              {/* Recovery Section */}
              <div className="recovery-section">
                <h4 className="recovery-title">¿Problemas para acceder?</h4>
                <p className="recovery-text">¿Se te olvidó la contraseña?</p>
                <p className="recovery-note">
                  Espera por favor, todavía no hay funcionalidad para recuperarla.
                </p>
              </div>
            </div>
          </div>

          {/* Right Column - Login Form */}
          <div className="right-column">
            <div className="form-container">
              {/* Form Header */}
              <div className="form-header">
                <div className="form-icon">🔒</div>
                <h2 className="form-title">Iniciar Sesión</h2>
                <p className="form-subtitle">¡Qué alegría tenerte de vuelta!</p>
              </div>

              {/* Error Alert */}
              {msg && (
                <div className="error-alert show">
                  <span className="error-icon">⚠️</span>
                  <span className="error-text">{msg}</span>
                </div>
              )}

              <form onSubmit={handleSubmit}>
                {/* Email Field */}
                <div className="form-field">
                  <label htmlFor="correo" className="form-label">Correo Electrónico *</label>
                  <div className="input-group">
                    <span className="input-icon">✉️</span>
                    <input
                      id="correo"
                      name="correo"
                      type="email"
                      className="form-input"
                      required
                      placeholder="tu@email.com"
                      value={form.correo}
                      onChange={handleChange}
                    />
                  </div>
                </div>

                {/* Password Field */}
                <div className="form-field">
                  <label htmlFor="contraseña" className="form-label">Contraseña *</label>
                  <div className="input-group">
                    <span className="input-icon">🔒</span>
                    <input
                      id="contraseña"
                      name="contraseña"
                      type={showPassword ? 'text' : 'password'}
                      className="form-input"
                      required
                      placeholder="Tu contraseña"
                      value={form.contraseña}
                      onChange={handleChange}
                    />
                    <button
                      type="button"
                      className="password-toggle"
                      onClick={togglePassword}
                      aria-label={showPassword ? 'Ocultar contraseña' : 'Mostrar contraseña'}
                    >
                      {showPassword ? '🙈' : '👁️'}
                    </button>
                  </div>
                </div>

                {/* Submit Button */}
                <button 
                  type="submit" 
                  className="submit-button"
                  disabled={loading}
                >
                  {loading ? (
                    <>
                      <span className="loading-spinner"></span>
                      Iniciando sesión...
                    </>
                  ) : (
                    '¡Entrar a Artisa!'
                  )}
                </button>
              </form>

              {/* Register Link */}
              <div className="register-link">
                <p className="register-text-bottom">
                  ¿No tienes cuenta? 
                  <Link to="/register" className="register-anchor">¡Regístrate aquí!</Link>
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
